attributeChangedCallback(attribute, oldValue, newValue) {
  if (!this.hasConnected) {
    return;
  }
  switch (attribute) {
    case "label":
      this.querySelector("a").textContent = newValue;
      break;
    case "url":
      this.querySelector("a").href = newValue;
      break;
    case "icon": {
      const icon = this.querySelector(".attachment-icon");
      if (!newValue) {
        icon.src = "";
        icon.srcset = "";
      } else if (newValue.startsWith("moz-icon://")) {
        icon.src = "";
        icon.srcset = lazy.makeMozIconSrcSet(newValue, 16);
      } else {
        icon.src = newValue;
        icon.srcset = "";
      }
    }
  }
